"""
Calibration and discrimination metrics for correctness probes.

Provides AUROC, ECE, and Brier score computation.
Dependencies: numpy, sklearn.
"""

import numpy as np
from sklearn.metrics import roc_auc_score


def compute_auroc(y_true: np.ndarray, y_prob: np.ndarray) -> float:
    y_true = np.asarray(y_true)
    y_prob = np.asarray(y_prob)
    if len(np.unique(y_true)) < 2:
        return float("nan")
    return float(roc_auc_score(y_true, y_prob))


def compute_ece(y_true: np.ndarray, y_prob: np.ndarray, n_bins: int = 15) -> float:
    """Expected Calibration Error with equal-width binning."""
    y_true = np.asarray(y_true, dtype=float)
    y_prob = np.asarray(y_prob, dtype=float)
    bin_edges = np.linspace(0.0, 1.0, n_bins + 1)
    ece = 0.0
    for lo, hi in zip(bin_edges[:-1], bin_edges[1:]):
        mask = (y_prob > lo) & (y_prob <= hi)
        if lo == 0.0:
            mask = (y_prob >= lo) & (y_prob <= hi)
        count = mask.sum()
        if count == 0:
            continue
        avg_confidence = y_prob[mask].mean()
        avg_accuracy = y_true[mask].mean()
        ece += (count / len(y_true)) * abs(avg_accuracy - avg_confidence)
    return float(ece)


def compute_brier(y_true: np.ndarray, y_prob: np.ndarray) -> float:
    y_true = np.asarray(y_true, dtype=float)
    y_prob = np.asarray(y_prob, dtype=float)
    return float(np.mean((y_prob - y_true) ** 2))


def compute_all_metrics(y_true: np.ndarray, y_prob: np.ndarray) -> dict:
    return {
        "auroc": compute_auroc(y_true, y_prob),
        "ece": compute_ece(y_true, y_prob),
        "brier": compute_brier(y_true, y_prob),
    }

"""
Data loading for cross-lingual calibration experiments.

Loads MMLU (English) and Global-MMLU (zh/hi/sw) from HuggingFace,
returns unified dicts with keys: question, choices, answer, language, subject.

Dependencies: datasets.
"""

import random
from typing import Optional

from datasets import load_dataset


ANSWER_LETTERS = ["A", "B", "C", "D"]


def load_mmlu_en(
    subjects: Optional[list[str]] = None,
    max_samples: Optional[int] = None,
    seed: int = 42,
) -> list[dict]:
    """Load English MMLU from cais/mmlu (all config, test split)."""
    ds = load_dataset("cais/mmlu", "all", split="test")
    items = []
    for row in ds:
        if subjects and row["subject"] not in subjects:
            continue
        items.append({
            "question": row["question"],
            "choices": list(row["choices"]),
            "answer": int(row["answer"]),
            "language": "en",
            "subject": row["subject"],
        })
    if max_samples and max_samples < len(items):
        rng = random.Random(seed)
        items = rng.sample(items, max_samples)
    return items


def load_global_mmlu(
    language: str,
    subjects: Optional[list[str]] = None,
    max_samples: Optional[int] = None,
    seed: int = 42,
) -> list[dict]:
    """Load Global-MMLU for a given language (zh, hi, sw, etc.)."""
    ds = load_dataset("CohereForAI/Global-MMLU", language, split="test")
    items = []
    for row in ds:
        if subjects and row["subject"] not in subjects:
            continue
        items.append({
            "question": row["question"],
            "choices": list(row["options"]),
            "answer": int(row["answer"]),
            "language": language,
            "subject": row["subject"],
        })
    if max_samples and max_samples < len(items):
        rng = random.Random(seed)
        items = rng.sample(items, max_samples)
    return items


def format_prompt(item: dict) -> str:
    """Format an MMLU item into a multiple-choice prompt string."""
    lines = [f"Question: {item['question']}"]
    for i, choice in enumerate(item["choices"]):
        lines.append(f"{ANSWER_LETTERS[i]}) {choice}")
    lines.append("Answer:")
    return "\n".join(lines)


def get_correctness_label(model_answer: int, gold_answer: int) -> int:
    return int(model_answer == gold_answer)


def load_dataset_by_name(
    name: str,
    language: str = "en",
    subjects: Optional[list[str]] = None,
    max_samples: Optional[int] = None,
) -> list[dict]:
    """Dispatcher: load by dataset name string."""
    if name == "mmlu" and language == "en":
        return load_mmlu_en(subjects=subjects, max_samples=max_samples)
    elif name == "global_mmlu":
        return load_global_mmlu(language, subjects=subjects, max_samples=max_samples)
    elif name == "mmlu" and language != "en":
        return load_global_mmlu(language, subjects=subjects, max_samples=max_samples)
    else:
        raise ValueError(f"Unknown dataset: {name}")

